DROP TABLE IF EXISTS `audit_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `audit_log` (
  `Audit_ID` varchar(10) NOT NULL,
  `Message_ID` varchar(10) NOT NULL,
  `Employee_ID` varchar(10) NOT NULL,
  `Action_Type` enum('Leave','WFH','Attendance','Employee Details') NOT NULL,
  `Action_Details` varchar(255) NOT NULL,
  `Old_Value` text,
  `New_Value` text,
  `Updated_By` varchar(100) NOT NULL,
  `Update_Timestamp` varchar(25) NOT NULL,
  `Status` enum('Success','Failed') NOT NULL,
  PRIMARY KEY (`Audit_ID`),
  KEY `Message_ID` (`Message_ID`),
  KEY `Employee_ID` (`Employee_ID`),
  CONSTRAINT `audit_log_ibfk_1` FOREIGN KEY (`Message_ID`) REFERENCES `email_transaction` (`Message_ID`),
  CONSTRAINT `audit_log_ibfk_2` FOREIGN KEY (`Employee_ID`) REFERENCES `employee_master` (`Employee_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
