--
-- Table structure for table `email_transaction`
--

DROP TABLE IF EXISTS `email_transaction`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `email_transaction` (
  `Message_ID` varchar(10) NOT NULL,
  `Employee_ID` varchar(10) NOT NULL,
  `To_Email` varchar(100) NOT NULL,
  `Subject` varchar(150) NOT NULL,
  `Email_Body` longtext NOT NULL,
  `Received_Datetime` varchar(100) DEFAULT NULL,
  `Processing_Status` varchar(20) NOT NULL,
  PRIMARY KEY (`Message_ID`),
  KEY `Employee_ID` (`Employee_ID`),
  CONSTRAINT `email_transaction_ibfk_1` FOREIGN KEY (`Employee_ID`) REFERENCES `employee_master` (`Employee_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

