LOCK TABLES `email_transaction` WRITE;
/*!40000 ALTER TABLE `email_transaction` DISABLE KEYS */;
INSERT INTO `email_transaction` VALUES ('MSG001','EMP001','hroperations263@gmail.com','Sick Leave Request','Hi HR Team,I have been running a high fever since last night and my doctor has advised me to take complete rest. I won\'t be able to attend the office tomorrow. Kindly approve one day of sick leave.Regards,Employee emp001','03-07-2026 08:15','Processed'),('MSG002','EMP002','hroperations263@gmail.com','Leave Required for Family Function','Hi HR,\nI would like to request leave on 7th July as I need to attend an important family function out of town. Kindly approve my leave request.Thanks,Employee emp002','05-07-2026 18:42','Processed'),('MSG003','EMP003','hroperations263@gmail.com','Request for Casual Leave','Dear HR Team,I have some personal work that requires my presence at home tomorrow. Please grant me casual leave for one day.Thank you.Employee emp003','06-07-2026 09:21','Processed'),('MSG004','EMP004','hroperations263@gmail.com','Medical Appointment','Hello HR,I have a scheduled medical appointment tomorrow morning and won\'t be able to report to work. Kindly approve my leave for the day.Regards,Employee emp004','08-07-2026 16:54','Processed'),('MSG005','EMP005','hroperations263@gmail.com','Emergency Leave','Hi HR,Due to an unexpected family emergency, I need to travel immediately. I request leave for today and tomorrow. Kindly consider my request.Regards,Employee emp005','09-07-2026 07:48','Processed'),('MSG006','EMP006','hroperations263@gmail.com','Leave Application','Dear HR,I am feeling unwell with severe body ache and headache today. I won\'t be able to come to the office. Kindly approve my sick leave.Thank you.Employee emp006','10-07-2026 08:37','Processed'),('MSG007','EMP007','hroperations263@gmail.com','Earned Leave Request','Hi HR Team,I am planning a short vacation with my family from 15th July to 17th July. Kindly approve my earned leave for these dates.Regards,Employee emp007','11-07-2026 19:26','Processed'),('MSG008','EMP008','hroperations263@gmail.com','Need Leave Tomorrow','Hello,I have to visit my hometown tomorrow due to some urgent personal work. Please approve my leave for one day.Thanks.Employee emp008','13-07-2026 20:11','Processed'),('MSG009','EMP009','hroperations263@gmail.com','Leave for Personal Reasons','Dear HR,I request leave on 16th July because of some unavoidable personal commitments. Kindly grant me leave for the day.\nRegards,Employee emp009','14-07-2026 09:58','Processed'),('MSG010','EMP010','hroperations263@gmail.com','Sick Leave','Hi HR,I woke up with a migraine and nausea this morning. I won\'t be able to work today. Kindly approve my sick leave.Regards,Employee emp010','15-07-2026 07:22','Processed'),('MSG011','EMP011','hroperations263@gmail.com','Leave request','Hello HR Team,I need to accompany my parents for an important hospital visit tomorrow. I request leave for the day. Please approve my application.Thank you.Employee emp011','17-07-2026 17:43','Processed'),('MSG012','EMP012','hroperations263@gmail.com','Requesting Leave for Two Days','Dear HR,I have some important personal work that requires me to travel outside the city. Kindly approve my leave for 21st and 22nd JulyRegards,Employee emp012','18-07-2026 11:36','Processed'),('MSG013','EMP013','hroperations263@gmail.com','One Day Leave Request','Hi HR,I won\'t be able to attend work tomorrow due to a family commitment. Please consider this as my leave request for one day.Thanks.Employee emp013','20-07-2026 18:09','Processed'),('MSG014','EMP014','hroperations263@gmail.com','Leave Due to Health Issues','Dear HR Team,\nI have been advised by my doctor to rest for two days because of a viral infection. Kindly approve my leave for the mentioned period.Regards,Employee emp014','22-07-2026 08:27','Processed'),('MSG015','EMP015','hroperations263@gmail.com','Leave Application for Personal Work','Hello HR,I need leave tomorrow to complete some important documentation work at the government office. Kindly approve my leave request.Thank you.Employee emp015','23-07-2026 16:18','Processed'),('MSG016','EMP016','hroperations263@gmail.com','Request to Work From Home Tomorrow','Hi HR Team,I am experiencing mild flu symptoms but feel well enough to work. I request permission to work from home tomorrow so I can continue my tasks while recovering.Regards,Employee emp016','03-07-2026 09:12','Processed'),('MSG017','EMP017','hroperations263@gmail.com','WFH Request Due to Plumbing Work','Dear HR,There is urgent plumbing maintenance scheduled at my residence tomorrow, and I need to be available at home. Kindly allow me to work from home for the day.Thank you.Employee emp017','05-07-2026 17:35','Processed'),('MSG018','EMP018','hroperations263@gmail.com','Work From Home Approval Request','Hello HR Team,I have a doctor\'s appointment in the afternoon tomorrow. To avoid taking leave, I would like to work from home for the day. Kindly approve my request.Regards,Employee emp018','06-07-2026 10:08','Processed'),('MSG019','EMP019','hroperations263@gmail.com','Request for Remote Work','Hi HR,Heavy rainfall has caused severe traffic disruptions in my area. I request permission to work remotely today so that my work is not affected.Regards,Employee emp019','08-07-2026 08:04','Processed'),('MSG020','EMP020','hroperations263@gmail.com','WFH for One Day','Dear HR Team,I need to stay home to receive an important delivery that requires my presence. Kindly allow me to work from home tomorrow.Thank you.Employee emp020','09-07-2026 18:27','Processed'),('MSG021','EMP021','hroperations263@gmail.com','Request to Work Remotely','Hello HR,My child is unwell today, and I need to take care of them. I will be available online throughout the day and request approval to work from home.Regards,Employee emp021','10-07-2026 07:55','Processed'),('MSG022','EMP022','hroperations263@gmail.com','WFH Request for Tomorrow','Hi HR Team,I have internet maintenance scheduled at my apartment during the morning hours. I request permission to work from home tomorrow and will ensure timely completion of my work.Regards,Employee emp022','11-07-2026 19:11','Processed'),('MSG023','EMP023','hroperations263@gmail.com','Request for Work From Home','Dear HR,I am expecting a technician to visit my residence for electrical repairs. Kindly approve my request to work from home tomorrow.Thank you.Employee emp023','13-07-2026 16:48','Processed'),('MSG024','EMP024','hroperations263@gmail.com','Remote Work Request','Hello HR Team,I have been advised to avoid travelling for a day because of a minor back strain. I would like to work from home tomorrow. Kindly consider my request.Regards,Employee emp024','14-07-2026 09:43','Processed'),('MSG025','EMP025','hroperations263@gmail.com','Work From Home Due to Personal Reason','Hi HR,I have some urgent personal commitments in the morning but will be available online for the rest of the day. Please allow me to work from home tomorrow.Regards,Employee emp025','15-07-2026 18:15','Processed'),('MSG026','EMP026','hroperations263@gmail.com','WFH Request','Dear HR Team,The road leading to my locality has been temporarily closed due to construction work. I request approval to work from home today.Thank you.Employee emp026','17-07-2026 08:21','Processed'),('MSG027','EMP027','hroperations263@gmail.com','Permission to Work From Home','Hello HR,\n\nI have a scheduled pest control service at my home tomorrow. Since I need to supervise the work, I request permission to work remotely for the day.\n\nRegards,\nEmployee emp027','18-07-2026 17:54','Processed'),('MSG028','EMP028','hroperations263@gmail.com','Request for Remote Working','Hi HR Team,I am recovering from a viral infection and would prefer to avoid travelling while continuing my office work. Kindly approve my request to work from home for tomorrow.Thank you.Employee emp028','20-07-2026 08:49','Processed'),('MSG029','EMP029','hroperations263@gmail.com','WFH Request for Medical Reasons','Dear HR,I have a follow-up medical consultation tomorrow afternoon. To avoid taking leave, I request permission to work from home for the entire day.Regards,Employee emp 029','22-07-2026 11:26','Processed'),('MSG030','EMP030','hroperations263@gmail.com','Request to Work From Home','Hello HR,I have an important inspection scheduled at my residence tomorrow morning. I will remain available throughout the day and request approval to work remotely.Thank you.Employee emp030','23-07-2026 16:37','Processed'),('MSG031','EMP031','hroperations263@gmail.com','Missing Punch-Out Correction Request','Hi HR Team,Yesterday my punch-out was not recorded due to a biometric machine issue. I had completed my regular working hours. Kindly update my attendance record.Regards,Employee emp031','04-07-2026 09:18','Processed'),('MSG032','EMP032','hroperations263@gmail.com','Attendance Regularization Request','Dear HR,I forgot to mark my check-in yesterday morning because I was attending an urgent client meeting directly. Kindly regularize my attendance.Thank you.Employee emp032','06-07-2026 10:42','Processed'),('MSG033','EMP033','hroperations263@gmail.com','Correction Required for Attendance','Hello HR,My attendance for yesterday is showing as absent even though I was present in the office throughout the day. Please verify and correct the record.Regards,Employee emp033','07-07-2026 08:56','Processed'),('MSG034','EMP034','hroperations263@gmail.com','Biometric Attendance Issue','Hi HR,The biometric device was not functioning properly while I was leaving the office yesterday, so my punch-out could not be recorded. Kindly update my attendance.Thank you.Employee emp034','09-07-2026 09:34','Processed'),('MSG035','EMP035','hroperations263@gmail.com','Request to Correct Attendance','Dear HR Team,I accidentally forgot to mark my attendance during check-in today. I reached the office at my usual time. Kindly make the necessary correction.Regards,Employee emp035','10-07-2026 09:11','Processed'),('MSG036','EMP036','hroperations263@gmail.com','Attendance Discrepa