DROP TABLE IF EXISTS `human_review`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `human_review` (
  `Review_ID` varchar(10) NOT NULL,
  `Message_ID` varchar(10) DEFAULT NULL,
  `Employee_ID` varchar(10) DEFAULT NULL,
  `Request_Type` enum('Leave','WFH','Attendance','Employee Details') DEFAULT NULL,
  `RAG_Decision` enum('Approved','Rejected','Needs Human Review') DEFAULT NULL,
  `RAG_Reason` varchar(255) DEFAULT NULL,
  `Human_Decision` enum('Pending','Approved','Rejected') DEFAULT 'Pending',
  `Final_Decision` enum('Pending','Approved','Rejected') DEFAULT 'Pending',
  `Reviewed_By` varchar(50) DEFAULT NULL,
  `Review_Date` datetime DEFAULT NULL,
  `Status` enum('Pending','Completed') DEFAULT 'Pending',
  PRIMARY KEY (`Review_ID`),
  KEY `Message_ID` (`Message_ID`),
  KEY `Employee_ID` (`Employee_ID`),
  CONSTRAINT `human_review_ibfk_1` FOREIGN KEY (`Message_ID`) REFERENCES `email_transaction` (`Message_ID`),
  CONSTRAINT `human_review_ibfk_2` FOREIGN KEY (`Employee_ID`) REFERENCES `employee_master` (`Employee_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

