INSERT INTO `human_review` VALUES ('REV001','MSG064','EMP045','Leave','Needs Human Review','The policy requires verification of employee ID existence, sufficient leave balance and valid dates which cannot be validated by AI.',NULL,'Pending',NULL,NULL,'Pending'),('REV002','MSG066','EMP045','Leave','Rejected','The maximum leave duration per request is 2 consecutive days, and this request is for a period longer than that.',NULL,'Pending',NULL,NULL,'Pending'),('REV003','MSG069','EMP045','Leave','Approved','Employee ID exists, sufficient leave balance is available, and the requested duration of 1 day complies with the minimum (0.5 days) and maximum (2 days) limits.',NULL,'Pending',NULL,NULL,'Pending'),('REV004','MSG071','EMP046','WFH','Approved','The employee is eligible for Work From Home and has not exceeded the maximum limit of 5 Work From Home days.',NULL,'Pending',NULL,NULL,'Pending'),('REV005','MSG072','EMP048','Attendance','Approved','The request is for a \'Missing Check-In\' and the reason provided, \'Biometric machine was not working,\' aligns with acceptable reasons outlined in the policy.',NULL,'Pending',NULL,NULL,'Pending'),('REV006','MSG073','EMP048','Attendance','Needs Human Review','The request is a duplicate, requiring manual review to determine appropriate action.',NULL,'Pending',NULL,NULL,'Pending'),('REV007','MSG091','EMP101','Attendance','Needs Human Review','The reason provided indicates a Biometric Device Malfunction, which requires human review according to policy rule #2.',NULL,'Pending',NULL,NULL,'Pending'),('REV008','MSG097','EMP122','Leave','Needs Human Review','The reason indicates an exceptional operational issue requiring human review as per policy rule #2.',NULL,'Pending',NULL,NULL,'Pending');
