/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_Fill_Attendance_August`()
BEGIN

    INSERT INTO Attendance_Transaction
    (
        Attendance_ID,
        Employee_ID,
        Attendance_Date,
        Check_In_Time,
        Check_Out_Time,
        Status
    )
    SELECT
        CONCAT(
            'ATT',
            5250 + ROW_NUMBER() OVER (
                ORDER BY e.Employee_ID, d.Attendance_Date
            )
        ) AS Attendance_ID,
        e.Employee_ID,
        d.Attendance_Date,
        '09:00:00',
        '18:00:00',
        'Present'
    FROM Employee_Master e
    CROSS JOIN
    (
        SELECT DATE_ADD('2026-08-13', INTERVAL n DAY) AS Attendance_Date
        FROM
        (
            SELECT 0 AS n UNION ALL SELECT 1 UNION ALL SELECT 2
            UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5
            UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8
            UNION ALL SELECT 9 UNION ALL SELECT 10 UNION ALL SELECT 11
            UNION ALL SELECT 12 UNION ALL SELECT 13 UNION ALL SELECT 14
        ) numbers
    ) d
    WHERE DAYOFWEEK(d.Attendance_Date) NOT IN (1, 7)
    AND NOT EXISTS
    (
        SELECT 1
        FROM Attendance_Transaction a
        WHERE a.Employee_ID = e.Employee_ID
        AND a.Attendance_Date = d.Attendance_Date
    );

END ;;
DELIMITER ;
