/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_Process_Attendance_Correction`(

    IN p_Message_ID VARCHAR(10),
    IN p_Employee_ID VARCHAR(10),
    IN p_Attendance_Date DATE,
    IN p_Correction_Type VARCHAR(30),
    IN p_New_CheckIn TIME,
    IN p_New_CheckOut TIME,
    IN p_Reason TEXT,
    IN p_Received_Date DATE

)
BEGIN

    DECLARE v_Employee_Count INT DEFAULT 0;
    DECLARE v_Message_Count INT DEFAULT 0;

    DECLARE v_Old_CheckIn TIME;
    DECLARE v_Old_CheckOut TIME;

    DECLARE v_Audit_ID VARCHAR(10);

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SELECT 'ERROR' AS Status,
               'Transaction Failed' AS Remarks;
    END;

    START TRANSACTION;


    SELECT CONCAT(
            'AUD',
            LPAD(
                IFNULL(MAX(CAST(SUBSTRING(Audit_ID,4) AS UNSIGNED)),0)+1,
                3,
                '0'
            )
           )
    INTO v_Audit_ID
    FROM Audit_Log;



    SELECT COUNT(*)
    INTO v_Employee_Count
    FROM Employee_Master
    WHERE Employee_ID=p_Employee_ID;

    IF v_Employee_Count=0 THEN

        ROLLBACK;

        SELECT 'ERROR' AS Status,
               'Employee does not exist.' AS Remarks;

    ELSE

    

        SELECT COUNT(*)
        INTO v_Message_Count
        FROM Email_Transaction
        WHERE Message_ID=p_Message_ID;

        IF v_Message_Count=0 THEN

            ROLLBACK;

            SELECT 'ERROR' AS Status,
                   'Message ID does not exist.' AS Remarks;

        ELSE

          

            SELECT Check_In_Time,
                   Check_Out_Time
            INTO v_Old_CheckIn,
                 v_Old_CheckOut
            FROM Attendance_Transaction
            WHERE Employee_ID=p_Employee_ID
            AND Attendance_Date=p_Attendance_Date;

            

            IF p_Correction_Type='Missing Check-In' THEN

                UPDATE Attendance_Transaction
                SET Check_In_Time =
                    IF(
                        p_New_CheckIn IS NULL,
                        '09:00:00',
                        p_New_CheckIn
                    ),
                    Status='Present'
                WHERE Employee_ID=p_Employee_ID
                AND Attendance_Date=p_Attendance_Date;

           

            ELSEIF p_Correction_Type='Missing Check-Out' THEN

                UPDATE Attendance_Transaction
                SET Check_Out_Time =
                    IF(
                        p_New_CheckOut IS NULL,
                        '18:00:00',
                        p_New_CheckOut
                    ),
                    Status='Present'
                WHERE Employee_ID=p_Employee_ID
                AND Attendance_Date=p_Attendance_Date;

          

            ELSEIF p_Correction_Type='Incorrect Check-In' THEN

                UPDATE Attendance_Transaction
                SET Check_In_Time=p_New_CheckIn,
                    Status='Present'
                WHERE Employee_ID=p_Employee_ID
                AND Attendance_Date=p_Attendance_Date;

            

            ELSEIF p_Correction_Type='Incorrect Check-Out' THEN

                UPDATE Attendance_Transaction
                SET Check_Out_Time=p_New_CheckOut,
                    Status='Present'
                WHERE Employee_ID=p_Employee_ID
                AND Attendance_Date=p_Attendance_Date;

            END IF;

          

            INSERT INTO Audit_Log
            (
                Audit_ID,
                Message_ID,
                Employee_ID,
                Action_Type,
                Action_Details,
                Old_Value,
                New_Value,
                Updated_By,
                Update_Timestamp,
                Status
            )
            VALUES
            (
                v_Audit_ID,
                p_Message_ID,
                p_Employee_ID,
                'Attendance',
                p_Correction_Type,

                CONCAT(
                    'CheckIn=',
                    IFNULL(v_Old_CheckIn,'NULL'),
                    ', CheckOut=',
                    IFNULL(v_Old_CheckOut,'NULL')
                ),

                CONCAT(
                    'CheckIn=',
                    IFNULL(
                        (SELECT Check_In_Time
                         FROM Attendance_Transaction
                         WHERE Employee_ID=p_Employee_ID
                         AND Attendance_Date=p_Attendance_Date),
                        'NULL'
                    ),
                    ', CheckOut=',
                    IFNULL(
                        (SELECT Check_Out_Time
                         FROM Attendance_Transaction
                         WHERE Employee_ID=p_Employee_ID
                         AND Attendance_Date=p_Attendance_Date),
                        'NULL'
                    )
                ),

                'AI',
                NOW(),
                'Success'
            );

            COMMIT;

            SELECT
                'Approved' AS Status,
                'Attendance Correction Processed Successfully' AS Remarks;

        END IF;

    END IF;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
