/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_Process_Information_Update`(

IN p_Message_ID VARCHAR(10),
IN p_Employee_ID VARCHAR(10),
IN p_Field_Name VARCHAR(50),
IN p_New_Value VARCHAR(255),
IN p_Decision VARCHAR(20),
IN p_Remarks VARCHAR(255)

)
BEGIN

DECLARE v_Employee_Count INT DEFAULT 0;
DECLARE v_Message_Count INT DEFAULT 0;

DECLARE EXIT HANDLER FOR SQLEXCEPTION
BEGIN
    ROLLBACK;
    SELECT 'ERROR' AS Status,
           'Transaction Failed' AS Remarks;
END;

START TRANSACTION;

SELECT COUNT(*) INTO v_Employee_Count
FROM Employee_Master
WHERE Employee_ID = p_Employee_ID;

IF v_Employee_Count = 0 THEN

    ROLLBACK;
    SELECT 'ERROR' AS Status,
           'Employee does not exist.' AS Remarks;

ELSE

    SELECT COUNT(*) INTO v_Message_Count
    FROM Email_Transaction
    WHERE Message_ID = p_Message_ID;

    IF v_Message_Count = 0 THEN

        ROLLBACK;
        SELECT 'ERROR' AS Status,
               'Message ID does not exist.' AS Remarks;

    ELSE

        IF p_Decision='Approved' THEN

            CASE p_Field_Name

                WHEN 'Email' THEN
                    UPDATE Employee_Master
                    SET Email = p_New_Value
                    WHERE Employee_ID = p_Employee_ID;

                WHEN 'Phone_Number' THEN
                    UPDATE Employee_Master
                    SET Phone_Number = p_New_Value
                    WHERE Employee_ID = p_Employee_ID;

                WHEN 'Aadhaar_Number' THEN
                    UPDATE Employee_Master
                    SET Aadhaar_Number = p_New_Value
                    WHERE Employee_ID = p_Employee_ID;

                WHEN 'Bank_Account_Number' THEN
                    UPDATE Employee_Master
                    SET Bank_Account_Number = p_New_Value
                    WHERE Employee_ID = p_Employee_ID;

                WHEN 'Address' THEN
                    UPDATE Employee_Master
                    SET Address = p_New_Value
                    WHERE Employee_ID = p_Employee_ID;

            END CASE;

            INSERT INTO Audit_Log
            (Audit_ID,Message_ID,Employee_ID,Action_Type,
             Action_Details,Old_Value,New_Value,
             Updated_By,Update_Timestamp,Status)
            VALUES
            (
                'AUD064',
                p_Message_ID,
                p_Employee_ID,
                'Employee Details',
                CONCAT(p_Field_Name,' Updated'),
                'Previous Value',
                p_New_Value,
                'AI',
                DATE_FORMAT(NOW(),'%Y-%m-%d %H:%i:%s'),
                'Success'
            );

            COMMIT;

            SELECT 'Approved' AS Status,
                   p_Remarks AS Remarks;

        ELSE

            INSERT INTO Audit_Log
            (Audit_ID,Message_ID,Employee_ID,Action_Type,
             Action_Details,Old_Value,New_Value,
             Updated_By,Update_Timestamp,Status)
            VALUES
            (
                'AUD064',
                p_Message_ID,
                p_Employee_ID,
                'Employee Details',
                'Information Update Rejected',
                'No Change',
                'No Change',
                'AI',
                DATE_FORMAT(NOW(),'%Y-%m-%d %H:%i:%s'),
                'Success'
            );

            COMMIT;

            SELECT 'Rejected' AS Status,
                   p_Remarks AS Remarks;

        END IF;

    END IF;

END IF;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_Process_Leave_Request` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_Process_Leave_Request`(

    IN p_Message_ID VARCHAR(10),
    IN p_Employee_ID VARCHAR(10),
    IN p_Leave_Type VARCHAR(50),
    IN p_Start_Date DATE,
    IN p_End_Date DATE,
    IN p_Reason TEXT,
    IN p_Received_Datetime VARCHAR(25)

)
BEGIN

    DECLARE v_Employee_Count INT DEFAULT 0;
    DECLARE v_Message_Count INT DEFAULT 0;
    DECLARE v_Duplicate_Count INT DEFAULT 0;

    DECLARE v_Leave_Days DECIMAL(4,1) DEFAULT 0;
    DECLARE v_Available_Balance DECIMAL(4,1) DEFAULT 0;
    DECLARE v_New_Balance DECIMAL(4,1) DEFAULT 0;

    DECLARE v_Monthly_Used DECIMAL(4,1) DEFAULT 0;
    DECLARE v_Audit_ID VARCHAR(10);

    DECLARE v_Processed_Leave_Type VARCHAR(50);

    DECLARE v_Current_Date DATE;


    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN

        ROLLBACK;

        SELECT
            'ERROR' AS Status,
            'Transaction Failed' AS Remarks;

    END;


    START TRANSACTION;


    /* =====================================================
       GENERATE AUDIT ID
       ===================================================== */

    SELECT CONCAT(
        'AUD',
        LPAD(
            COALESCE(
                MAX(
                    CAST(
                        SUBSTRING(Audit_ID,4)
                        AS UNSIGNED
                    )
                ),
                0
            ) + 1,
            3,
            '0'
        )
    )
    INTO v_Audit_ID
    FROM Audit_Log;


    /* =====================================================
       EMPLOYEE VALIDATION
       ===================================================== */

    SELECT COUNT(*)
    INTO v_Employee_Count
    FROM Employee_Master
    WHERE Employee_ID = p_Employee_ID;


    IF v_Employee_Count = 0 THEN

        ROLLBACK;

        SELECT
            'Rejected' AS Status,
            'Employee does not exist.' AS Remarks;


    ELSE


        /* =================================================
           MESSAGE VALIDATION
           ================================================= */

        SELECT COUNT(*)
        INTO v_Message_Count
        FROM Email_Transaction
        WHERE Message_ID = p_Message_ID;


        IF v_Message_Count = 0 THEN

            ROLLBACK;

            SELECT
                'Rejected' AS Status,
                'Message ID does not exist.' AS Remarks;


        ELSE


            /* =============================================
               DATE VALIDATION
               ============================================= */

            IF p_Start_Date IS NULL
               OR p_End_Date IS NULL
               OR p_Start_Date > p_End_Date THEN

                ROLLBACK;

                SELECT
                    'Rejected' AS Status,
                    'Invalid leave dates.' AS Remarks;


            ELSE


                /* =========================================
                   CALCULATE WORKING LEAVE DAYS
                   
                   Monday-Friday = Counted
                   Saturday-Sunday = Not Counted
                   ========================================= */

                SET v_Leave_Days = 0;

                SET v_Current_Date = p_Start_Date;

                WHILE v_Current_Date <= p_End_Date DO

                    IF DAYOFWEEK(v_Current_Date) NOT IN (1,7) THEN

                        SET v_Leave_Days =
                            v_Leave_Days + 1;

                    END IF;

                    SET v_Current_Date =
                        DATE_ADD(
                            v_Current_Date,
                            INTERVAL 1 DAY
                        );

                END WHILE;


                /* =========================================
                   IF NO WORKING DAYS
                   ========================================= */

                IF v_Leave_Days = 0 THEN

                    ROLLBACK;

                    SELECT
                        'Rejected' AS Status,
                        'The requested period contains no working days.'
                        AS Remarks;


                ELSE


                    /* =====================================
                       SICK / CASUAL → PAID LEAVE
                       ===================================== */

                    SET v_Processed_Leave_Type = p_Leave_Type;


                    IF p_Leave_Type IN
                       ('Sick Leave','Casual Leave') THEN

                        SET v_Processed_Leave_Type =
                            'Paid Leave';

                        UPDATE Leave_Transaction

                        SET Leave_Type = 'Paid Leave'

                        WHERE Message_ID = p_Message_ID;

                    END IF;


                    /* =====================================
                       DUPLICATE REQUEST CHECK
                       ===================================== */

                    SELECT COUNT(*)
                    INTO v_Duplicate_Count

                    FROM Leave_Transaction

                    WHERE Employee_ID = p_Employee_ID

                      AND Leave_Transaction_ID <> (

                          SELECT Leave_Transaction_ID

                          FROM Leave_Transaction

                          WHERE Message_ID = p_Message_ID

                          LIMIT 1

                      )

                      AND Start_Date <= p_End_Date

                      AND End_Date >= p_Start_Date

                      AND Status = 'Approved';


                    IF v_Duplicate_Count > 0 THEN

                        ROLLBACK;

                        SELECT
                            'Rejected' AS Status,
                            'Duplicate leave request already exists for the requested period.'
                            AS Remarks;


                    ELSE


                        /* =================================
                           PAID LEAVE
                           LP-001
                           ================================= */

                        IF v_Processed_Leave_Type = 'Paid Leave' THEN


                            /* Maximum 2 working days */

                            IF v_Leave_Days > 2 THEN

                                ROLLBACK;

                                SELECT
                                    'Rejected' AS Status,
                                    'Paid Leave cannot exceed 2 working days per request.'
                                    AS Remarks;


                            ELSE


                                /* =================================
                                   MONTHLY PAID LEAVE LIMIT
                                   WEEKENDS EXCLUDED
                                   ================================= */

                                SELECT COALESCE(
                                    SUM(

                                        DATEDIFF(
                                            End_Date,
                                            Start_Date
                                        ) + 1

                                        -

                                        FLOOR(
                                            (
                                                DATEDIFF(
                                                    End_Date,
                                                    Start_Date
                                                )
                                                + DAYOFWEEK(Start_Date)
                                            ) / 7
                                        )

                                        -

                                        FLOOR(
                                            (
                                                DATEDIFF(
                                                    End_Date,
                                                    Start_Date
                                                )
                                                + DAYOFWEEK(Start_Date)
                                                + 1
                                            ) / 7
                                        )

                                    ),
                                    0
                                )

                                INTO v_Monthly_Used

                                FROM Leave_Transaction

                                WHERE Employee_ID = p_Employee_ID

                                  AND Leave_Type = 'Paid Leave'

                                  AND Status = 'Approved'

                                  AND YEAR(Start_Date) =
                                      YEAR(p_Start_Date)

                                  AND MONTH(Start_Date) =
                                      MONTH(p_Start_Date);


                                IF v_Monthly_Used + v_Leave_Days > 3 THEN

                                    ROLLBACK;

                                    SELECT
                                        'Rejected' AS Status,
                                        'Paid Leave monthly limit of 3 working days exceeded.'
                                        AS Remarks;


                                ELSE


                                    /* =================================
                                       CHECK PAID LEAVE BALANCE
                                       ================================= */

                                    SELECT Paid_Leave

                                    INTO v_Available_Balance

                                    FROM Leave_Balance

                                    WHERE Employee_ID = p_Employee_ID

                                    FOR UPDATE;


                                    IF v_Available_Balance < v_Leave_Days THEN

                                        ROLLBACK;

                                        SELECT
                                            'Rejected' AS Status,
                                            'Insufficient Paid Leave balance.'
                                            AS Remarks;


                                    ELSE


                                        SET v_New_Balance =
                                            v_Available_Balance
                                            - v_Leave_Days;


                                        /* =============================
                                           UPDATE BALANCE
                                           ============================= */

                                        UPDATE Leave_Balance

                                        SET Paid_Leave =
                                            v_New_Balance

                                        WHERE Employee_ID =
                                            p_Employee_ID;


                                        /* =============================
                                           UPDATE TRANSACTION
                                           ============================= */

                                        UPDATE Leave_Transaction

                                        SET
                                            Leave_Type = 'Paid Leave',
                                            Status = 'Approved',
                                            Remarks = 'Auto Approved'

                                        WHERE Message_ID =
                                            p_Message_ID;


                                        /* =============================
                                           UPDATE ATTENDANCE
                                           WEEKENDS EXCLUDED
                                           ============================= */

                                        UPDATE Attendance_Transaction

                                        SET Status = 'Leave'

                                        WHERE Employee_ID =
                                            p_Employee_ID

                                          AND Attendance_Date
                                              BETWEEN p_Start_Date
                                              AND p_End_Date

                                          AND DAYOFWEEK(
                                              Attendance_Date
                                          ) NOT IN (1,7);


                                        /* =============================
                                           AUDIT LOG
                                           ============================= */

                                        INSERT INTO Audit_Log
                                        (
                                            Audit_ID,
                                            Message_ID,
                                            Employee_ID,
                                            Action_Type,
                                            Action_Details,
                                            Old_Value,
                                            New_Value,
                                            Updated_By,
                                            Update_Timestamp,
                                            Status
                                        )

                                        VALUES
                                        (
                                            v_Audit_ID,
                                            p_Message_ID,
                                            p_Employee_ID,
                                            'Leave',
                                            'Leave Request Approved',
                                            CONCAT(
                                                'Paid Leave = ',
                                                v_Available_Balance
                                            ),
                                            CONCAT(
                                                'Paid Leave = ',
                                                v_New_Balance
                                            ),
                                            'AI',
                                            NOW(),
                                            'Success'
                                        );


