DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_Process_WFH_Request`(
    IN p_Message_ID VARCHAR(10),
    IN p_Employee_ID VARCHAR(10),
    IN p_From_Date DATE,
    IN p_To_Date DATE,
    IN p_Reason TEXT,
    IN p_Received_Date DATE
)
BEGIN

    DECLARE v_Employee_Count INT DEFAULT 0;
    DECLARE v_Message_Count INT DEFAULT 0;
    DECLARE v_Audit_ID VARCHAR(10);

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SELECT 'ERROR' AS Status,
               'Transaction Failed' AS Remarks;
    END;

    START TRANSACTION;

    SELECT CONCAT(
        'AUD',
        LPAD(
            IFNULL(MAX(CAST(SUBSTRING(Audit_ID,4) AS UNSIGNED)),0)+1,
            3,
            '0'
        )
    )
    INTO v_Audit_ID
    FROM Audit_Log;


    SELECT COUNT(*)
    INTO v_Employee_Count
    FROM Employee_Master
    WHERE Employee_ID = p_Employee_ID;

    IF v_Employee_Count = 0 THEN

        ROLLBACK;

        SELECT 'ERROR' AS Status,
               'Employee does not exist.' AS Remarks;

    ELSE

        SELECT COUNT(*)
        INTO v_Message_Count
        FROM Email_Transaction
        WHERE Message_ID = p_Message_ID;

        IF v_Message_Count = 0 THEN

            ROLLBACK;

            SELECT 'ERROR' AS Status,
                   'Message ID does not exist.' AS Remarks;

        ELSE

           
            UPDATE WFH_Transaction
            SET
                Status='Approved',
                Remarks='Auto Approved'
            WHERE Message_ID=p_Message_ID;

           

            UPDATE Attendance_Transaction
            SET Status='WFH'
            WHERE Employee_ID=p_Employee_ID
            AND Attendance_Date BETWEEN p_From_Date AND p_To_Date;

          

            INSERT INTO Audit_Log
            (
                Audit_ID,
                Message_ID,
                Employee_ID,
                Action_Type,
                Action_Details,
                Old_Value,
                New_Value,
                Updated_By,
                Update_Timestamp,
                Status
            )
            VALUES
            (
                v_Audit_ID,
                p_Message_ID,
                p_Employee_ID,
                'WFH',
                'WFH Request Approved',
                'Pending',
                'Approved',
                'AI',
                NOW(),
                'Success'
            );

            COMMIT;

            SELECT
                'Approved' AS Status,
                'WFH Request Approved Successfully' AS Remarks;

        END IF;

    END IF;

END ;;
